def copy_messages_to_inquiry(apps, schema_editor):
    """Carry legacy ``Messages`` rows into ``Inquiry`` with field translation.

    Runs while both tables still exist (between CreateModel and DeleteModel).
    Idempotent: skips (name, email, created_at) triples that already landed, so
    a re-run or a fumbled forward-apply won't duplicate inquiries.
    """
    Messages = apps.get_model('myapp', 'Messages')
    Inquiry = apps.get_model('myapp', 'Inquiry')
    Service = apps.get_model('dashboardapp', 'Service')

    # Title -> Service, so legacy free-text services ("Web") become real FKs.
    services_by_title = {s.title: s for s in Service.objects.all()}

    for old in Messages.objects.all().iterator():
        service_text = (old.service or '').strip()

        # Dedupe on the natural key used everywhere else in this project.
        if Inquiry.objects.filter(
            name=old.name, email=old.email, created_at=old.created_at
        ).exists():
            continue

        # bool response -> status choice.
        status = 'replied' if old.response else 'new'

        new = Inquiry(
            name=old.name,
            email=old.email,
            phone=old.phone,
            service=services_by_title.get(service_text),
            service_title=service_text,
            note=old.note,
            status=status,
        )
        new.save()

        # created_at is auto_now_add, so it stamps "now" on insert and would
        # silently destroy the original submission dates. Force them back with
        # a raw UPDATE (also stamps responded_at for already-answered rows).
        Inquiry.objects.filter(pk=new.pk).update(
            created_at=old.created_at,
            **(
                {'responded_at': old.response_at}
                if status == 'replied' and old.response_at
                else {}
            ),
        )


